import * as Icons from "lucide-react";
import type { LucideIcon } from "lucide-react";

/** A real Lucide icon component is a `forwardRef` generated by
 * `createLucideIcon(name, iconNode)`, which gives it an explicit
 * `displayName`. The module also exports a few PascalCase symbols that
 * aren't icons — the generic `Icon` component (its `render` is anonymous and
 * it requires an `iconNode` prop this selector never provides: rendering it
 * as-is crashes) and `LucideProvider` (a context provider, not a
 * `forwardRef`). Filtering on the component's shape rather than name casing
 * excludes both without depending on a hardcoded name list.
 *
 * `render.name` is NOT a reliable filter here: in dev, React's
 * `displayName` setter rewrites `render.name` as a side effect, but the
 * production build doesn't — `render.name` would then be empty and this
 * filter would exclude every icon once packaged. `displayName` is assigned
 * explicitly and unconditionally by `createLucideIcon` in both builds. */
function isIconComponent(value: unknown): value is LucideIcon {
  const component = value as { render?: unknown; displayName?: unknown } | null | undefined;
  return typeof component?.render === "function" && Boolean(component.displayName);
}

const ICON_ENTRIES = Object.entries(Icons).filter(
  ([name, value]) => /^[A-Z]/.test(name) && isIconComponent(value),
) as Array<[string, LucideIcon]>;

export const LUCIDE_ICON_NAMES: string[] = ICON_ENTRIES.map(([name]) => name).sort();

const ICON_MAP = new Map(ICON_ENTRIES);

/** `null` if the name matches no known icon (never chosen, or chosen then
 * renamed/removed by a later Lucide update) — the caller should then simply
 * render nothing. */
export function resolveLucideIcon(name: string | null): LucideIcon | null {
  if (!name) return null;
  return ICON_MAP.get(name) ?? null;
}
